import{_ as i,l as r,o as e,c as n,v as o,p as s,x as l,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"调用约定的实现","description":"","frontmatter":{"title":"调用约定的实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/calling-convention-impl.md","filePath":"cs/calling-convention-impl.md","lastUpdated":1789023840000}'),A={name:"cs/calling-convention-impl.md"};function h(m,a,_,u,B,I){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="调用约定的实现" tabindex="-1">调用约定的实现 <a class="header-anchor" href="#调用约定的实现" aria-label="Permalink to &quot;调用约定的实现&quot;">​</a></h1><div class="epigraph"><p>约定规定参数在哪些寄存器或栈槽、谁保存、返回值怎么走。后端 lowering 必须与 ABI 文档一致，否则不能与已编译的库链接。</p><footer>—— 据 System V ABI；ARM AAPCS；主干[调用约定与栈](/cs/calling-convention-stack)；Appel 整理</footer></div><p>上一课<a href="/cs/target-description">目标描述</a>有寄存器类。组成课已讲约定直觉。缺口是<strong>实现</strong>：ISel 把 <code>call</code> 降成拷贝到参数寄存器、栈对齐、red zone、可变参。本课钉 lowering，不重画栈帧全图——下一课布局。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IR 的 <code>call @f(i32, double)</code> 要按 ABI 分类（整数/浮点/聚合）。聚合：寄存器对或内存。缺口是<strong>分类算法 + 插入拷贝</strong>，不是 lex。</p><p>可变参：固定参数后的区域；调用方与 <code>va_list</code> 一致。调用者保存：跨 call 的活寄存器要存——分配器已见预着色。</p><h3 id="abi-不是「编译器随便选」" tabindex="-1">ABI 不是「编译器随便选」 <a class="header-anchor" href="#abi-不是「编译器随便选」" aria-label="Permalink to &quot;ABI 不是「编译器随便选」&quot;">​</a></h3><p>与操作系统、语言运行时绑定。自创约定只能闭世界 LTO 静态全程序。不要改 <code>printf</code> 的约定。</p><p><span class="marginnote">SysV AMD64 ABI。AAPCS64。Itanium C++ ABI 的 this 指针。本课 C 为主，C++ 额外 this、返回槽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现 <code>LowerCall</code>/<code>LowerFormalArguments</code>：把参数映射到物理寄存器或 <code>FrameIndex</code>。返回：寄存器或 sret 隐藏指针。对齐：栈 16 字节等。</p>',11)),(e(),s(p,null,{default:l(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%20%E5%8F%82%E6%95%B0%22%5D%20--%3E%20CLS%5B%22ABI%20%E5%88%86%E7%B1%BB%22%5D%0A%20%20CLS%20--%3E%20REG%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20CLS%20--%3E%20STK%5B%22%E6%A0%88%E6%A7%BD%22%5D%0A%20%20REG%20--%3E%20CALL%5B%22call%20%E5%BA%8F%E5%88%97%22%5D%0A%20%20STK%20--%3E%20CALL%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与内联：内联后约定消失。与尾调用：须约定兼容才能 jmp。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浮点与 SIMD 寄存器类独立。整数 8 个参数寄存器满则上栈。不要把 <code>float</code> 误分类到 GPR 除非 ABI 如此（某些软浮点）。</p><p>异常：调用是 invoke 时还要 landing pad，展开表后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 DWARF。后课默认：call lowering 实现 ABI。下一课栈帧布局与帧指针。</p><p>也不把 ABI 当 REST API。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调用约定 lowering：分类 → 寄存器/栈 → 拷贝。</li><li>必须与平台 ABI 一致才能链接 libc。</li><li>可变参、聚合、sret 是细节坑。</li><li>出处：System V ABI；AAPCS；对照龙书/Appel 调用序列。</li></ul>',9))])}const E=i(A,[["render",h]]);export{S as __pageData,E as default};
